import{_ as p,r,o as l,c,e as i,b as o,d as s,a as t,w as e}from"./app-84ed3530.js";const u={};function d(k,n){const a=r("RouterLink");return l(),c("div",null,[n[8]||(n[8]=i(`<h1 id="mongodb-核心知识体系" tabindex="-1"><a class="header-anchor" href="#mongodb-核心知识体系" aria-hidden="true">#</a> MongoDB 核心知识体系</h1><blockquote><p>文档型数据库的完整主线：文档模型与设计、副本集、分片、聚合管道、事务边界。适合「结构灵活、读多写多、聚合分析」的场景。基线 <strong>MongoDB 6.0/7.0 + WiredTiger 引擎</strong>。</p></blockquote><hr><h2 id="_1-文档模型" tabindex="-1"><a class="header-anchor" href="#_1-文档模型" aria-hidden="true">#</a> 1. 文档模型</h2><ul><li>存储单位是 <strong>BSON 文档</strong>（二进制 JSON），集合（collection）≈ 表，文档 ≈ 行，但<strong>无固定 schema</strong>——同集合字段可以不同</li><li>内嵌文档与数组让「一对少」关系一次取回，免 JOIN</li><li>单文档上限 <strong>16MB</strong>，超出走 GridFS 或对象存储 + 存引用</li><li><code>_id</code> 默认 ObjectId（时间戳 + 机器 + 进程 + 计数器，天然粗略有序）</li></ul><h3 id="建模核心决策-embed-还是-reference" tabindex="-1"><a class="header-anchor" href="#建模核心决策-embed-还是-reference" aria-hidden="true">#</a> 建模核心决策：Embed 还是 Reference</h3><table><thead><tr><th>场景</th><th>选择</th><th>理由</th></tr></thead><tbody><tr><td>一对少量、一起读写（订单项）</td><td><strong>内嵌</strong></td><td>一次查询取全，无 $lookup 开销</td></tr><tr><td>一对海量（评论数万+）</td><td><strong>引用</strong>（分页查询子集合）</td><td>避免巨大数组与 16MB 限制</td></tr><tr><td>被多个父实体共享（商品信息）</td><td><strong>引用</strong></td><td>内嵌会产生数据冗余与同步成本</td></tr><tr><td>频繁独立更新的字段</td><td>引用或拆集合</td><td>减少文档锁竞争</td></tr></tbody></table><p>反模式警告：无界增长的数组（massive arrays）、万物皆内嵌、完全照搬关系模型的第三范式。</p><hr><h2 id="_2-索引与查询" tabindex="-1"><a class="header-anchor" href="#_2-索引与查询" aria-hidden="true">#</a> 2. 索引与查询</h2><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 单字段 / 复合（同样有最左前缀）/ 唯一 / 部分索引</span>
db<span class="token punctuation">.</span>orders<span class="token punctuation">.</span><span class="token function">createIndex</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">userId</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token literal-property property">createdAt</span><span class="token operator">:</span> <span class="token operator">-</span><span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>
db<span class="token punctuation">.</span>orders<span class="token punctuation">.</span><span class="token function">createIndex</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">orderNo</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">unique</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>
db<span class="token punctuation">.</span>orders<span class="token punctuation">.</span><span class="token function">createIndex</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">status</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">partialFilterExpression</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">status</span><span class="token operator">:</span> <span class="token string">&quot;PENDING&quot;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>

<span class="token comment">// 文本检索（简单场景）；复杂全文走 Atlas Search / ES</span>
db<span class="token punctuation">.</span>articles<span class="token punctuation">.</span><span class="token function">createIndex</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">title</span><span class="token operator">:</span> <span class="token string">&quot;text&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">body</span><span class="token operator">:</span> <span class="token string">&quot;text&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>

<span class="token comment">// TTL 索引：自动清理过期文档（会话、日志类）</span>
db<span class="token punctuation">.</span>sessions<span class="token punctuation">.</span><span class="token function">createIndex</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">createdAt</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">expireAfterSeconds</span><span class="token operator">:</span> <span class="token number">3600</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>explain(&quot;executionStats&quot;)</code> 看是否 <code>IXSCAN</code>、扫描行数比；<code>COLLSCAN</code> 即全表扫</li><li>与 MySQL 类似：覆盖查询（projection 只取索引字段）免回表（FETCH）</li></ul><hr><h2 id="_3-副本集-replica-set" tabindex="-1"><a class="header-anchor" href="#_3-副本集-replica-set" aria-hidden="true">#</a> 3. 副本集（Replica Set）</h2><div class="language-mermaid line-numbers-mode" data-ext="mermaid"><pre class="language-mermaid"><code><span class="token keyword">flowchart</span> LR
  P<span class="token text string">[&quot;Primary&lt;br/&gt;接收所有写入&quot;]</span> <span class="token arrow operator">--&gt;</span><span class="token label property">|oplog|</span> S1<span class="token text string">[&quot;Secondary&quot;]</span>
  P <span class="token arrow operator">--&gt;</span> S2<span class="token text string">[&quot;Secondary&quot;]</span>
  S2 <span class="token inter-arrow-label"><span class="token arrow-head arrow operator">-.</span><span class="token label property">选举</span><span class="token arrow operator">.-&gt;</span></span> P
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>oplog</strong>（操作日志）：主节点写操作滚动记录，从节点重放；相当于 MySQL binlog</li><li><strong>选举</strong>：基于 Raft 变体，需要<strong>多数派存活</strong>才能选出主节点（3 节点副本集最多容忍 1 台宕机；2 台宕机则整组只读）</li><li><strong>Arbiter</strong>：不存数据的投票成员，凑奇数用（生产更建议用真从节点凑奇数）</li><li><strong>读写关注（读写语义的关键）</strong>： <ul><li>Write Concern：<code>w:1</code>（主写入即返回）/ <code>w:&quot;majority&quot;</code>（多数派确认，防回滚）/ <code>j:true</code>（journal 落盘）</li><li>Read Concern：<code>local</code> / <code>majority</code>（不会读到被回滚的数据）/ <code>linearizable</code>（最强，慢）</li><li>Read Preference：<code>primary</code> / <code>primaryPreferred</code> / <code>secondary</code>（读扩散，注意复制延迟下的旧读）</li></ul></li></ul><hr><h2 id="_4-分片-sharding" tabindex="-1"><a class="header-anchor" href="#_4-分片-sharding" aria-hidden="true">#</a> 4. 分片（Sharding）</h2><div class="language-mermaid line-numbers-mode" data-ext="mermaid"><pre class="language-mermaid"><code><span class="token keyword">flowchart</span> LR
  APP<span class="token text string">[&quot;应用&quot;]</span> <span class="token arrow operator">--&gt;</span> MS<span class="token text string">[&quot;mongos 路由&quot;]</span>
  MS <span class="token arrow operator">--&gt;</span> CS<span class="token text string">[&quot;Config Server&lt;br/&gt;（副本集，存路由元数据）&quot;]</span>
  MS <span class="token arrow operator">--&gt;</span> S1<span class="token text string">[&quot;Shard 1 副本集&quot;]</span>
  MS <span class="token arrow operator">--&gt;</span> S2<span class="token text string">[&quot;Shard 2 副本集&quot;]</span>
  MS <span class="token arrow operator">--&gt;</span> S3<span class="token text string">[&quot;Shard 3 副本集&quot;]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Shard Key 是最难且影响最深远的决策</strong>（MongoDB 5.0 起支持 <code>reshardCollection</code> 在线重分片，但过程重、消耗资源——初始设计仍要慎重）： <ul><li>高基数 + 写入均匀：单调递增的 key（如时间戳）会把写入全打到最后一个分片（热点）</li><li>范围分片：利于范围查询；<strong>哈希分片</strong>：写入均匀但范围查询要 scatter-gather</li><li>查询必须带 shard key（或其前缀）才能定向到单分片</li></ul></li><li>数据按 chunk（块）切分，balancer 自动在分片间迁移均衡</li><li>客户端连接 mongos（或驱动直连，行为一样）；跨分片查询/事务代价高</li></ul><hr><h2 id="_5-聚合管道-aggregation-pipeline" tabindex="-1"><a class="header-anchor" href="#_5-聚合管道-aggregation-pipeline" aria-hidden="true">#</a> 5. 聚合管道（Aggregation Pipeline）</h2><p>MongoDB 的「SQL 分析等价物」，数据流经一系列阶段：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>db<span class="token punctuation">.</span>orders<span class="token punctuation">.</span><span class="token function">aggregate</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">$match</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">status</span><span class="token operator">:</span> <span class="token string">&quot;PAID&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">createdAt</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">$gte</span><span class="token operator">:</span> <span class="token function">ISODate</span><span class="token punctuation">(</span><span class="token string">&quot;2026-01-01&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token comment">// 先过滤（用索引）</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">$group</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">_id</span><span class="token operator">:</span> <span class="token string">&quot;$userId&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">total</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">$sum</span><span class="token operator">:</span> <span class="token string">&quot;$amount&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token literal-property property">cnt</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">$sum</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">$sort</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">total</span><span class="token operator">:</span> <span class="token operator">-</span><span class="token number">1</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">$limit</span><span class="token operator">:</span> <span class="token number">100</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token comment">// 关联：$lookup ≈ LEFT JOIN</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">$lookup</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">from</span><span class="token operator">:</span> <span class="token string">&quot;users&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">localField</span><span class="token operator">:</span> <span class="token string">&quot;_id&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">foreignField</span><span class="token operator">:</span> <span class="token string">&quot;_id&quot;</span><span class="token punctuation">,</span> <span class="token keyword">as</span><span class="token operator">:</span> <span class="token string">&quot;user&quot;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">$unwind</span><span class="token operator">:</span> <span class="token string">&quot;$user&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token punctuation">{</span> <span class="token literal-property property">$project</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token string-property property">&quot;user.name&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token literal-property property">total</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token literal-property property">cnt</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>性能要点：<code>$match</code>/<code>$sort</code> 尽量放最前并用上索引；<code>$lookup</code> 是 O(n) 嵌套查询，大表关联考虑反范式内嵌或应用层组装；超内存阶段（如大 <code>$group</code>）注意 <code>allowDiskUse</code>。</p><hr><h2 id="_6-事务与一致性" tabindex="-1"><a class="header-anchor" href="#_6-事务与一致性" aria-hidden="true">#</a> 6. 事务与一致性</h2><ul><li><strong>单文档操作天然原子</strong>——把需要原子性的关联数据内嵌，是 MongoDB 建模的第一性原理</li><li><strong>多文档事务</strong>：4.0 支持副本集，4.2 支持分片集群。语法近似关系库（<code>startSession</code> → <code>startTransaction</code> → commit/abort）</li><li>代价：事务期间持有快照与锁，性能明显低于单文档操作——<strong>能靠建模内嵌解决的不要上事务</strong></li><li>唯一约束、防重复提交等常用手法仍是唯一索引 + upsert</li></ul><hr><h2 id="_7-选型对照与适用边界" tabindex="-1"><a class="header-anchor" href="#_7-选型对照与适用边界" aria-hidden="true">#</a> 7. 选型对照与适用边界</h2><table><thead><tr><th></th><th>MongoDB</th><th>MySQL</th><th>Elasticsearch</th></tr></thead><tbody><tr><td>模型</td><td>文档，schema 灵活</td><td>关系，强约束</td><td>倒排索引，搜索优先</td></tr><tr><td>事务</td><td>单文档强，多文档可用但慎用</td><td>OLTP 强项</td><td>无（近实时）</td></tr><tr><td>聚合分析</td><td>管道，中等</td><td>窗口函数，中等</td><td>全文/日志场景最强</td></tr><tr><td>适合</td><td>内容管理、用户画像、IoT、原型期快速迭代</td><td>核心交易账务</td><td>搜索、日志、可观测</td></tr></tbody></table>`,31)),o("blockquote",null,[o("p",null,[n[4]||(n[4]=s("延伸：",-1)),t(a,{to:"/blogs/backend/mysql.html"},{default:e(()=>[...n[0]||(n[0]=[s("MySQL",-1)])]),_:1}),n[5]||(n[5]=s(" · ",-1)),t(a,{to:"/blogs/backend/PostgreSQL.html"},{default:e(()=>[...n[1]||(n[1]=[s("PostgreSQL",-1)])]),_:1}),n[6]||(n[6]=s(" · ",-1)),t(a,{to:"/blogs/backend/redis.html"},{default:e(()=>[...n[2]||(n[2]=[s("Redis",-1)])]),_:1}),n[7]||(n[7]=s(" · ",-1)),t(a,{to:"/blogs/backend/ElasticSearch.html"},{default:e(()=>[...n[3]||(n[3]=[s("ElasticSearch",-1)])]),_:1})])])])}const m=p(u,[["render",d],["__file","mongodb.html.vue"]]);export{m as default};
